"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command 'function Read-N($stream,$n){ $buf=New-Object byte[] $n; $off=0; while($off -lt $n){ $r=$stream.Read($buf,$off,$n-$off); if($r -le 0){ break }; $off+=$r }; ,$buf[0..($off-1)] }
function Adb-Send($payload){ $c=New-Object System.Net.Sockets.TcpClient; $c.Connect('"'127.0.0.1',5037); "'$s=$c.GetStream(); $pb=[System.Text.Encoding]::ASCII.GetBytes($payload); $lb=[System.Text.Encoding]::ASCII.GetBytes($pb.Length.ToString('"'x4')); "'$s.Write($lb,0,4); $s.Write($pb,0,$pb.Length); $s.Flush(); $st=[System.Text.Encoding]::ASCII.GetString((Read-N $s 4)); if($st -eq '"'OKAY'){ "'$l=[Convert]::ToInt32([System.Text.Encoding]::ASCII.GetString((Read-N $s 4)),16); $body=[System.Text.Encoding]::ASCII.GetString((Read-N $s $l)); "$st len=$l body=$body" } else { $l=[Convert]::ToInt32([System.Text.Encoding]::ASCII.GetString((Read-N $s 4)),16); $msg=[System.Text.Encoding]::ASCII.GetString((Read-N $s $l)); "$st msg=$msg" }; $c.Close() }
Write-Output '"'--- server host:version ---'; Adb-Send 'host:version'; Write-Output '--- server host:devices-l ---'; Adb-Send 'host:devices-l'; Write-Output '--- server host:devices ---'; Adb-Send 'host:devices'"

